with deduped as (select *, rank() over (partition by order_id order by unit_price desc) as rn from order_items qualify rn = 1) select order_id, product_id, case when unit_price >= 400 then 'LARGE' else 'SMALL' end as unit_price_tier, avg(quantity) as avg_quantity, sum(unit_price) as total_unit_price, round(avg(quantity), 2) as avg_quantity_2, max(quantity) as max_quantity, round(avg(unit_price), 2) as avg_unit_price, stddev_samp(quantity) as quantity_stddev, grouping(order_id) as grouping_level from deduped group by rollup (order_id, product_id, case when unit_price >= 400 then 'LARGE' else 'SMALL' end) having stddev_samp(quantity) < 1000000 order by unit_price_tier desc;
